const KATALOG = {"regeln":{"catalog":{"version":"0.1.0","valid_from":"2026-09-12","scope":{"direction":"export_third_country","mode":"sea","preference_claimed":true},"disclaimer":"Rechtsverweise aus Sekundärrecherche, vor produktivem Einsatz gegen konsolidierte EUR-Lex-Fassungen und zoll.de zu verifizieren. Toleranzwerte sind Praxisannahmen, keine gesetzlichen Toleranzen.\n"},"defaults":{"comparison":"normalized_only","on_low_confidence":"re_extraction_required","low_confidence_below":0.8},"rules":[{"id":"VAL-01","name":"Rechnungssumme schlüssig","hardness":"hard","risk":"financial","inputs":["rechnung.positionen[].netto","rechnung.zuschlaege","rechnung.rabatte","rechnung.gesamt"],"assertion":"sum(positionen.netto) + zuschlaege - rabatte == gesamt","tolerance":{"amount":0.01,"per":"rounding_level"},"legal_basis":"Art. 70 UZK (Transaktionswert)","legal_source":"secondary","consequence":"Zollwertbasis unzuverlässig, Rückfrage Zoll, Zollwertschätzung","valid_from":"2026-09-12"},{"id":"VAL-03","name":"Kostenlose Position hat Zollwert","hardness":"hard","risk":"financial","inputs":["rechnung.positionen[].einzelpreis","rechnung.positionen[].zollwert","rechnung.positionen[].bewertungsmethode"],"assertion":"einzelpreis == 0 implies (zollwert > 0 or bewertungsmethode is set)","legal_basis":"Art. 74 UZK (Folgemethoden)","legal_source":"secondary","consequence":"'No charge' bedeutet nicht 'kein Zollwert'. Keine Freigabe ohne Bewertung.","valid_from":"2026-09-12"},{"id":"ORG-02","name":"Präferenzursprung deckt Ware","hardness":"hard","risk":"financial","inputs":["rechnung.positionen[].ursprung","praeferenznachweis.ursprung","praeferenznachweis.warenkreis","rechnung.positionen[].hs6"],"assertion":"origin matches and line is covered by goods_scope","legal_basis":"Ursprungsprotokoll des jeweiligen Abkommens; Art. 64 UZK","legal_source":"secondary","consequence":"Präferenzverlust, Nacherhebung bis 3 Jahre (Art. 103 UZK)","open_question":"Wortlaut und Wertgrenze je Abkommen zu parametrisieren","valid_from":"2026-09-12"},{"id":"ORG-03","name":"A.TR ist kein Ursprungsnachweis","hardness":"hard","risk":"compliance","inputs":["dokumente[].typ","praeferenznachweis.typ","sachverhalt.praeferenz_beansprucht"],"assertion":"atr_present must not set preferential_origin","legal_basis":"Beschluss 1/2006 EU-Türkei (Freiverkehrsnachweis)","legal_source":"secondary","consequence":"Unberechtigte Präferenz, Nacherhebung","note":"Häufigster fachlicher Denkfehler bei Nicht-Zöllnern","valid_from":"2026-09-12"},{"id":"ORG-06","name":"Wertgrenze Ursprungserklärung","hardness":"hard","risk":"financial","inputs":["praeferenznachweis.typ","praeferenznachweis.rex_nummer","praeferenznachweis.ursprungswert"],"assertion":"typ == origin_declaration and ursprungswert > threshold implies rex_nummer is present and structurally valid\n","parameters":{"threshold":{"value":6000,"currency":"EUR","basis":"value_of_originating_goods"}},"legal_basis":"Art. 61-66 UZK-IA","legal_source":"secondary","consequence":"Nachweis formell unwirksam, Präferenzverlust","note":"Schwelle bezieht sich auf Ursprungswaren, nicht auf den Rechnungsgesamtwert","valid_from":"2026-09-12"},{"id":"CLS-01","name":"HS-6 konsistent über alle Belege","hardness":"hard","risk":"financial","inputs":["rechnung.positionen[].hs6","packliste.positionen[].hs6","praeferenznachweis.warenkreis[].hs6"],"assertion":"first `digits` digits identical across all documents referencing the line","parameters":{"digits":6},"legal_basis":"Tarifierung; Ursprungsregeln sind HS-basiert","legal_source":"secondary","consequence":"Nacherhebung, Präferenzverlust, Tarifierungsstreit","valid_from":"2026-09-12"},{"id":"CLS-02","name":"Stellenzahl Warennummer","hardness":"hard","risk":"data_quality","inputs":["anmeldung.warennummern","anmeldung.richtung"],"assertion":"richtung == export implies length == length_by_direction.export","parameters":{"length_by_direction":{"export":8,"import_de":11}},"legal_basis":"KN 8-stellig Ausfuhr, EZT-Codenummer 11-stellig Einfuhr (zoll.de)","legal_source":"secondary","consequence":"Maßnahmen- und Zollsatzermittlung nicht möglich","valid_from":"2026-09-12"},{"id":"QTY-01","name":"Menge Rechnung gegen Packliste","hardness":"hard","risk":"operational","inputs":["rechnung.positionen[].menge","packliste.positionen[].menge","packliste.backorders"],"assertion":"rechnung.menge == packliste.menge - dokumentierte backorders","legal_basis":"Keine eigenständige Norm, Konsistenz der Anmeldedaten","legal_source":"practice","consequence":"Mengenabweichung beeinflusst Wert, Ursprung und Beschau","valid_from":"2026-09-12"},{"id":"QTY-03","name":"Gewichtslogik","hardness":"hard","risk":"data_quality","inputs":["packliste.packstuecke[].brutto_kg","packliste.packstuecke[].netto_kg"],"assertion":"brutto_kg >= netto_kg > 0","legal_basis":"Logische Konsistenz","legal_source":"practice","consequence":"Datenfehler, Rohmasse in Anmeldung unbrauchbar","valid_from":"2026-09-12"},{"id":"TRN-01","name":"Containernummer konsistent","hardness":"hard","risk":"operational","inputs":["bill_of_lading.container_id","packliste.container_id"],"assertion":"normalized container ids identical","legal_basis":"Gestellung, Verschlusssicherheit","legal_source":"practice","consequence":"Bezeichnet ggf. eine andere physische Sendung, Beschau","valid_from":"2026-09-12"},{"id":"TRN-02","name":"Container-Prüfziffer ISO 6346","hardness":"hard","risk":"data_quality","inputs":["bill_of_lading.container_id","packliste.container_id"],"assertion":"modulo 11 check digit valid","algorithm":{"letters":"A=10, Vielfache von 11 übersprungen, bis Z=38","weights":"2^0 bis 2^9 von links","modulus":11,"remainder_10_maps_to":0},"legal_basis":"ISO 6346; Owner-Register bei BIC","legal_source":"secondary","consequence":"OCR-Nachprüfung auslösen, nicht fachlich ablehnen","on_fail":"re_extraction_required","valid_from":"2026-09-12"},{"id":"REF-03","name":"Nur finale Dokumentversionen","hardness":"hard","risk":"compliance","inputs":["dokumente[].status","dokumente[].version","herkunft"],"assertion":"only documents with status == final may feed canonical facts","legal_basis":"Art. 15 UZK (Richtigkeit der Angaben)","legal_source":"secondary","consequence":"Draft-B/L oder Verify Copy als Anmeldegrundlage, Korrekturpflicht","valid_from":"2026-09-12"},{"id":"CUS-05","name":"Ausfuhrbegleitdokument deckt Rechnung und Packliste","hardness":"hard","risk":"compliance","inputs":["abd.positionen[].warennummer","abd.positionen[].nr","abd.container_id","rechnung.positionen[].hs6","packliste.container_id"],"assertion":"first `digits` digits of abd.warennummer identical to rechnung.hs6 for the same position number, every position on both sides, and abd.container_id identical to packliste.container_id after normalization\n","parameters":{"digits":6},"legal_basis":"Art. 263 UZK (Ausfuhranmeldung); Vorgangsidentität (docs/03, CUS-01)","legal_source":"secondary","consequence":"Angemeldet ist ein anderer Zollvorgang als verladen wird; Beschau, Berichtigung der Anmeldung","note":"Die MRN wird hier nicht geprüft. Struktur sichert die Normalisierung, Vorhandensein PFL-07; die Prüfziffer bleibt offen (docs/08).","valid_from":"2026-09-12"},{"id":"QTY-02","name":"Bruttogewicht Packliste gegen B/L","hardness":"soft","escalate_to_hard_at":{"relative":0.1},"risk":"operational","inputs":["packliste.brutto_gesamt_kg","bill_of_lading.brutto_kg"],"assertion":"absolute difference within tolerance","tolerance":{"relative":0.01,"absolute_kg":2,"apply":"greater_of"},"legal_basis":"Keine gesetzliche EU-Zolltoleranz. VGM-Pflicht nach SOLAS Kap. VI Regel 2 erzwingt verlässliche Verladerangabe; Toleranzen sind vertraglich.\n","legal_source":"practice","consequence":"Warnung, Rückfrage beim Verlader","valid_from":"2026-09-12"}]},"pflichtmatrix":{"version":"0.1.0","valid_from":"2026-09-12","scope":{"direction":"export_third_country","mode":"sea","preference_claimed":true},"entries":[{"id":"PFL-01","required_data":"rechnung.gesamt","label":"Rechnungsbetrag als Bewertungsgrundlage","required_evidence":["handelsrechnung","proformarechnung"],"required_document_form":"none","hardness":"hard","legal_basis":"Art. 163 UZK, Art. 145 UZK-IA (Unterlagen zur Anmeldung)","legal_source":"secondary"},{"id":"PFL-02","required_data":"rechnung.positionen.0.hs6","label":"Warennummer mindestens auf HS-6 je Position","required_evidence":["handelsrechnung","anmeldung"],"required_document_form":"none","hardness":"hard","legal_basis":"Art. 263 UZK; Anhang B UZK-DA (Datenelemente der Ausfuhranmeldung)","legal_source":"secondary"},{"id":"PFL-03","required_data":"packliste.brutto_gesamt_kg","label":"Rohmasse der Sendung","required_evidence":["packliste","bill_of_lading"],"required_document_form":"none","hardness":"hard","legal_basis":"Anhang B UZK-DA (Rohmasse als Datenelement); keine Papierpflicht für die Packliste","legal_source":"secondary"},{"id":"PFL-04","required_data":"bill_of_lading.container_id","label":"Container der Sendung","required_evidence":["bill_of_lading","sea_waybill"],"required_document_form":"none","hardness":"hard","legal_basis":"Gestellung; Seefrachtrecht §§ 513 ff. HGB","legal_source":"secondary"},{"id":"PFL-05","required_data":"praeferenznachweis.ursprung","label":"Präferenzursprung, weil Präferenz beansprucht wird","required_evidence":["eur1","eur_med","origin_declaration"],"required_document_form":"none","condition":"sachverhalt.praeferenz_beansprucht == true","hardness":"hard","legal_basis":"Ursprungsprotokoll des jeweiligen Abkommens; Art. 64 UZK","legal_source":"secondary","note":"EUR.1 und Ursprungserklärung auf der Rechnung erfüllen dieselbe Anforderung. A.TR erfüllt sie nicht (ORG-03).\n"},{"id":"PFL-07","required_data":"abd.mrn","label":"MRN der überlassenen Ausfuhranmeldung","required_evidence":["abd","aes_nachricht"],"required_document_form":"none","hardness":"hard","legal_basis":"Art. 263 UZK (Ausfuhranmeldung); Art. 137 UZK-DA (elektronische Anmeldung über 1.000 EUR oder 1.000 kg)","legal_source":"secondary","note":"Das ABD (Ausfuhrbegleitdokument) und die AES-Statusnachricht tragen dieselbe MRN. Die Schwelle aus Art. 137 UZK-DA ist hier nicht als Bedingung modelliert: Die Pflichtmatrix kennt nur Gleichheitsbedingungen, und jede Testakte liegt darüber. Unter der Schwelle wäre der Eintrag falsch; das steht in docs/OFFENE-PUNKTE.md, sobald ein Sachverhalt darunter kommt. Das ABD ist nicht der Ausgangsvermerk (docs/01, CUS-02).\n"},{"id":"PFL-06","required_data":"sachverhalt.incoterm.code","label":"Incoterm mit benanntem Ort","required_evidence":["handelsrechnung","kaufvertrag"],"required_document_form":"none","hardness":"soft","legal_basis":"Incoterms 2020 (ICC); Zollwertfolgen Art. 71/72 UZK","legal_source":"secondary"}]},"zustaendigkeiten":{"version":"0.1.0","owners":{"rechnung":{"primaer":"Lieferant/Verkäufer","sekundaer":"Einkauf","ausloeser":"Bestellung bestätigt"},"packliste":{"primaer":"Lieferant/Packbetrieb","sekundaer":"Spediteur/Lager","ausloeser":"Ware gepackt"},"bill_of_lading":{"primaer":"Seefrachtspediteur/Carrier","sekundaer":"Shipper","ausloeser":"SI-Cut-off / On-board"},"praeferenznachweis":{"primaer":"Exporteur/Lieferant","sekundaer":"Ursprungsstelle","ausloeser":"vor Ausfuhr"},"anmeldung":{"primaer":"Zollvertreter/Spediteur","sekundaer":"interne Zollabteilung","ausloeser":"nach Überlassung"},"abd":{"primaer":"Zollvertreter/Spediteur","sekundaer":"interne Zollabteilung","ausloeser":"nach Überlassung"},"sachverhalt":{"primaer":"Sachbearbeitung Export","sekundaer":"Vertrieb","ausloeser":"Auftragsanlage"},"dokumente":{"primaer":"Sachbearbeitung Export","sekundaer":"Spediteur","ausloeser":"Eingang der finalen Fassung"}},"escalation":[{"stufe":"erinnerung_0","zeitpunkt":"sofort nach Feststellung","bezug":null,"vorlauf_stunden":0,"adressat":"primaer"},{"stufe":"erinnerung_1","zeitpunkt":"vor internem Customs Cut-off","bezug":"customs_cutoff","vorlauf_stunden":48,"adressat":"primaer + operativer Sachbearbeiter"},{"stufe":"eskalation_1","zeitpunkt":"vor Carrier-/Terminal-Cut-off","bezug":"carrier_cutoff","vorlauf_stunden":48,"adressat":"Teamleitung"},{"stufe":"eskalation_2","zeitpunkt":"vor ETA/Abholung","bezug":"eta","vorlauf_stunden":72,"adressat":"Einkauf, Logistikleitung, Zollverantwortlicher"},{"stufe":"stop","zeitpunkt":"Cut-off erreicht","bezug":"carrier_cutoff","vorlauf_stunden":0,"adressat":"Anmeldung, Verladung oder Freigabe blockieren"}],"versand":{"mindestabstand_stunden":24,"verteiler":{"standard":"sachbearbeitung@zollpilot.test","Lieferant/Verkäufer":"lieferant@zollpilot.test","Lieferant/Packbetrieb":"lieferant@zollpilot.test","Exporteur/Lieferant":"lieferant@zollpilot.test","Seefrachtspediteur/Carrier":"spediteur@zollpilot.test","Zollvertreter/Spediteur":"spediteur@zollpilot.test","Sachbearbeitung Export":"sachbearbeitung@zollpilot.test","Teamleitung":"teamleitung@zollpilot.test","Extraktion (Nachlesen)":"sachbearbeitung@zollpilot.test"}}}};

// ---- src/normalisierung.mjs ----
// Normalisierung vor jedem Vergleich (CLAUDE.md, harte Grenze 2). Alle
// Regelvergleiche laufen ausschließlich auf normalisierten Werten. Was hier
// nicht abgedeckt ist — Währungsumrechnung mit Kurs und Kursdatum, UN/LOCODE,
// semantische Ähnlichkeit von Warenbeschreibungen — ist bewusst nicht gebaut
// und steht in docs/OFFENE-PUNKTE.md.

const FLOAT_RESERVE = 1e-9;

const RECHTSFORMEN = [
  'gmbh & co. kg', 'gmbh & co kg', 'gmbh', 'ag', 'kg', 'ohg', 'ug', 'se', 'e.k.', 'ek',
  'ltd', 'ltd.', 'limited', 'inc', 'inc.', 'llc', 'corp', 'corp.', 'co.', 'co', 'plc',
  's.a.', 'sa', 's.r.l.', 'srl', 'b.v.', 'bv', 'n.v.', 'nv', 'sarl', 's.à r.l.', 'sas',
];

/**
 * Firmenname: Rechtsformsuffixe entfernen, Kleinschreibung, Sonderzeichen und
 * Mehrfachleerzeichen reduzieren. Exakte IDs (EORI, USt-IdNr.) haben vor dem
 * Namensvergleich Vorrang — das hier ist die Fuzzy-Stufe, nie allein
 * entscheidend.
 */
function normalisiereFirmenname(roh) {
  if (!roh) return '';
  let name = String(roh).toLowerCase().replace(/[.,;:()"']/g, ' ').replace(/\s+/g, ' ').trim();
  for (const form of RECHTSFORMEN) {
    const suffix = ` ${form.replace(/[.]/g, '')}`;
    if (name.endsWith(suffix)) name = name.slice(0, -suffix.length).trim();
  }
  return name;
}

/**
 * Betrag aus Belegtext: "1.250,00", "1,250.00", "1250" werden zur Zahl 1250.
 * Entscheidet über das Dezimaltrennzeichen anhand des letzten Trennzeichens.
 */
function normalisiereBetrag(roh) {
  if (roh === null || roh === undefined || roh === '') return null;
  if (typeof roh === 'number') return roh;
  let text = String(roh).replace(/[^\d,.\-]/g, '');
  if (!/\d/.test(text)) return null;
  const letztesKomma = text.lastIndexOf(',');
  const letzterPunkt = text.lastIndexOf('.');
  if (letztesKomma > letzterPunkt) {
    text = text.replace(/\./g, '').replace(',', '.');
  } else {
    text = text.replace(/,/g, '');
  }
  const zahl = Number(text);
  return Number.isFinite(zahl) ? zahl : null;
}

/** Warencodes auf eine gemeinsame Stellenzahl kürzen; Leerzeichen und Punkte entfernen. */
function kuerzeWarencode(roh, stellen) {
  if (roh === null || roh === undefined) return null;
  const code = String(roh).replace(/[\s.]/g, '');
  if (!/^[0-9]+$/.test(code)) return null;
  return code.slice(0, stellen);
}

/** Ländercodes: ISO 3166-1 alpha-2, Großschreibung. "EU" ist kein Land (docs/01). */
function normalisiereLand(roh) {
  if (!roh) return null;
  const land = String(roh).trim().toUpperCase();
  return /^[A-Z]{2}$/.test(land) ? land : null;
}

/** Zwei Zahlen sind gleich, wenn ihr Abstand die Toleranz nicht überschreitet. */
function gleichBisAuf(a, b, toleranz) {
  if (a === null || b === null || a === undefined || b === undefined) return false;
  // Kleine Reserve gegen Gleitkommarauschen: 100.01 - 100 ist nicht 0.01.
  return Math.abs(a - b) <= toleranz + FLOAT_RESERVE;
}

// Darstellungshelfer. Sie liegen hier und nicht in den Regeln, damit
// src/regeln/ frei von nackten Zahlen bleibt (scripts/regel-check.mjs).
const NACHKOMMASTELLEN_ANTEIL = 4;
const NACHKOMMASTELLEN_PROZENT = 1;
const PROZENT = 100;

/** Anteil (0..1) auf vier Nachkommastellen. */
function gerundet(anteil) {
  return Number(anteil.toFixed(NACHKOMMASTELLEN_ANTEIL));
}

/** Anteil (0..1) als Prozenttext, z. B. "5.8 %". */
function prozent(anteil) {
  return `${(anteil * PROZENT).toFixed(NACHKOMMASTELLEN_PROZENT)} %`;
}

// ---- src/validatoren/container.mjs ----
// Container-Kennung nach ISO 6346: drei Buchstaben Eigner, ein Kategoriebuchstabe
// (U, J oder Z), sechs Ziffern Seriennummer, eine Prüfziffer. Vollständig offline
// prüfbar (docs/04-stammdaten-formate.md). Die Prüfziffer erkennt Lese- und
// Übertragungsfehler; sie beweist weder Eigentum noch Status des Containers.
//
// Die Zahlen hier sind technische Konstanten des Standards, keine fachlichen
// Schwellen. Deshalb liegen sie im Validator, nicht in rules.yaml.

const CONTAINER_MUSTER = /^[A-Z]{3}[UJZ][0-9]{7}$/;

const LAENGE_OHNE_PRUEFZIFFER = 10;
const MODUL_ISO6346 = 11;
const BUCHSTABEN_START = 10; // A = 10
const ASCII_A = 65;

/** Entfernt Leerzeichen, Bindestriche und Kleinschreibung: "MSKU 123456-5" wird "MSKU1234565". */
function normalisiereContainerId(roh) {
  if (roh === null || roh === undefined) return null;
  return String(roh).toUpperCase().replace(/[\s-]/g, '');
}

/**
 * Buchstabenwert nach ISO 6346: A = 10, danach fortlaufend unter Auslassung der
 * Vielfachen von 11. Also B = 12, C = 13, K = 21, L = 23, U = 32, Z = 38.
 */
function buchstabenwert(zeichen) {
  const index = zeichen.charCodeAt(0) - ASCII_A;
  // Zählen statt rechnen: Von A an hochzählen und jedes Vielfache von 11
  // überspringen. Eine geschlossene Formel war beim ersten Versuch bei L falsch
  // (22 statt 23) — die Schleife ist in zwei Sätzen erklärbar, die Formel nicht.
  let wert = BUCHSTABEN_START;
  for (let i = 0; i < index; i += 1) {
    wert += 1;
    if (wert % MODUL_ISO6346 === 0) wert += 1;
  }
  return wert;
}

/** Berechnet die Prüfziffer für die ersten zehn Zeichen. Rest 10 wird als 0 dargestellt. */
function containerPruefziffer(id) {
  const kopf = normalisiereContainerId(id).slice(0, LAENGE_OHNE_PRUEFZIFFER);
  if (!/^[A-Z]{4}[0-9]{6}$/.test(kopf)) return null;
  let summe = 0;
  for (let i = 0; i < LAENGE_OHNE_PRUEFZIFFER; i += 1) {
    const zeichen = kopf[i];
    const wert = /[A-Z]/.test(zeichen) ? buchstabenwert(zeichen) : Number(zeichen);
    summe += wert * 2 ** i;
  }
  return (summe % MODUL_ISO6346) % 10;
}

/**
 * Ergebnis der Strukturprüfung. `format` sagt, ob die Kennung überhaupt wie
 * eine Containernummer aussieht; `pruefziffer` sagt, ob die letzte Stelle
 * stimmt. Beides getrennt, weil ein Formatfehler ein anderes Signal ist als ein
 * Prüfziffernfehler.
 */
function pruefeContainerId(roh) {
  const id = normalisiereContainerId(roh);
  if (!id || !CONTAINER_MUSTER.test(id)) {
    return { id, format: false, pruefziffer: false, erwartet: null };
  }
  const erwartet = containerPruefziffer(id);
  const tatsaechlich = Number(id[LAENGE_OHNE_PRUEFZIFFER]);
  return { id, format: true, pruefziffer: erwartet === tatsaechlich, erwartet };
}

// ---- src/validatoren/awb.mjs ----
// Air Waybill: drei Stellen Airline-Präfix, acht Stellen Seriennummer, deren
// letzte die Prüfziffer ist. Die siebenstellige Seriennummer wird durch 7
// geteilt, der Rest ist die achte Ziffer. Der Präfix ist nicht Teil der
// Rechnung (docs/04-stammdaten-formate.md).
//
// Luftfracht liegt außerhalb des MVP-Sachverhalts; der Validator ist trotzdem
// hier, weil er vollständig offline prüfbar ist und das Datenmodell ihn
// vorsieht (docs/01, Air Waybill).

const AWB_MUSTER = /^[0-9]{3}-?[0-9]{8}$/;

const PRAEFIX_LAENGE = 3;
const SERIE_LAENGE = 7;
const MODUL_AWB = 7;

function normalisiereAwb(roh) {
  if (roh === null || roh === undefined) return null;
  return String(roh).replace(/[\s-]/g, '');
}

function pruefeAwb(roh) {
  const awb = normalisiereAwb(roh);
  if (!awb || !/^[0-9]{11}$/.test(awb)) {
    return { awb, format: false, pruefziffer: false, praefix: null, erwartet: null };
  }
  const praefix = awb.slice(0, PRAEFIX_LAENGE);
  const serie = awb.slice(PRAEFIX_LAENGE, PRAEFIX_LAENGE + SERIE_LAENGE);
  const erwartet = Number(serie) % MODUL_AWB;
  const tatsaechlich = Number(awb[PRAEFIX_LAENGE + SERIE_LAENGE]);
  return { awb, format: true, pruefziffer: erwartet === tatsaechlich, praefix, erwartet };
}

// ---- src/validatoren/ustid.mjs ----
// Deutsche USt-IdNr.: "DE" und neun Ziffern, die neunte ist die Prüfziffer nach
// ISO/IEC 7064 MOD 11,10. Offline berechenbar, aber nur über Sekundärquellen
// belegt (docs/08-known-unknowns.md). Bei kritischer Anwendung zusätzlich VIES
// bzw. qualifizierte Bestätigung nach § 18e UStG — das ist Stufe 2 und läuft
// nie blockierend.

const USTID_DE_MUSTER = /^DE[0-9]{9}$/;

const ZIFFERN_OHNE_PRUEFZIFFER = 8;
const MOD_10 = 10;
const MOD_11 = 11;

function normalisiereUstId(roh) {
  if (roh === null || roh === undefined) return null;
  return String(roh).toUpperCase().replace(/[\s.-]/g, '');
}

/** MOD 11,10 über die ersten acht Ziffern. */
function ustIdPruefziffer(ziffern) {
  let produkt = MOD_10;
  for (const zeichen of ziffern.slice(0, ZIFFERN_OHNE_PRUEFZIFFER)) {
    let summe = (Number(zeichen) + produkt) % MOD_10;
    if (summe === 0) summe = MOD_10;
    produkt = (2 * summe) % MOD_11;
  }
  const pruef = MOD_11 - produkt;
  return pruef === MOD_10 ? 0 : pruef;
}

function pruefeUstIdDe(roh) {
  const id = normalisiereUstId(roh);
  if (!id || !USTID_DE_MUSTER.test(id)) {
    return { id, format: false, pruefziffer: false, erwartet: null };
  }
  const ziffern = id.slice(2);
  const erwartet = ustIdPruefziffer(ziffern);
  const tatsaechlich = Number(ziffern[ZIFFERN_OHNE_PRUEFZIFFER]);
  return { id, format: true, pruefziffer: erwartet === tatsaechlich, erwartet };
}

// ---- src/validatoren/formate.mjs ----
// Regex-Vorfilter für Kennungen (docs/04-stammdaten-formate.md). Ein Regex
// beweist nur das Format, nie die Vergabe. Für EORI, REX, UN/LOCODE und TARIC
// braucht die Gültigkeit zwingend einen Online-Lookup (Stufe 2, nicht
// blockierend). Die MRN-Prüfziffer ist bewusst nicht implementiert, siehe
// docs/08-known-unknowns.md: Strukturprüfung ja, Algorithmus ungeklärt.

const FORMATE = Object.freeze({
  eori: /^[A-Z]{2}[A-Z0-9]{1,15}$/,
  mrn: /^[0-9]{2}[A-Z]{2}[A-Z0-9]{13}[A-Z0-9]$/,
  hs6: /^[0-9]{6}$/,
  kn8: /^[0-9]{8}$/,
  taric10: /^[0-9]{10}$/,
  ezt11: /^[0-9]{11}$/,
  ustid_de: /^DE[0-9]{9}$/,
  rex: /^[A-Z]{2}REX[A-Z0-9]+$/,
  unlocode: /^[A-Z]{2}[A-Z2-9]{3}$/,
  container: /^[A-Z]{3}[UJZ][0-9]{7}$/,
  awb: /^[0-9]{3}-?[0-9]{8}$/,
});

const INCOTERMS_2020 = Object.freeze([
  'EXW', 'FCA', 'CPT', 'CIP', 'DAP', 'DPU', 'DDP', 'FAS', 'FOB', 'CFR', 'CIF',
]);

/** Klauseln, die nur für See- und Binnenschiffstransport vorgesehen sind. */
const INCOTERMS_NUR_SEE = Object.freeze(['FAS', 'FOB', 'CFR', 'CIF']);

function formatGueltig(art, wert) {
  const muster = FORMATE[art];
  if (!muster) throw new Error(`Unbekannte Kennungsart: ${art}`);
  if (wert === null || wert === undefined) return false;
  return muster.test(String(wert));
}

/**
 * Ein Incoterm ohne benannten Ort ist unvollständig. Das ist eine Warnung, keine
 * Blockade (docs/04, "Incoterms als Datenmodell").
 */
function pruefeIncoterm(incoterm) {
  if (!incoterm || !incoterm.code) return { gueltig: false, warnungen: ['Incoterm fehlt'] };
  const code = String(incoterm.code).toUpperCase();
  const warnungen = [];
  if (!INCOTERMS_2020.includes(code)) return { gueltig: false, warnungen: [`Unbekannte Klausel ${code}`] };
  if (!incoterm.named_place) warnungen.push('benannter Ort fehlt');
  if (!incoterm.edition) warnungen.push('Edition fehlt (erwartet 2020)');
  return { gueltig: true, code, nurSee: INCOTERMS_NUR_SEE.includes(code), warnungen };
}

// ---- src/akte/aufbau.mjs ----
// Aufbau der Akte aus Assertions (CLAUDE.md, Prinzip 2).
//
// Eingang: eine Sendung mit `dokumente[]` und `assertions[]`. Jede Assertion
// ist, was ein Beleg sagt: Dokument, Pfad, Wert, Rohwert, Konfidenz, Fundstelle.
// Ausgang: dieselbe Sendung plus `fakten` (der Aktenwert je Pfad) und
// `herkunft` (welches Dokument mit welcher Konfidenz den Fakt gesetzt hat).
//
// Zwei Zusagen, die REF-03 und OCR-01 tragen:
//   1. Nur Assertions aus Dokumenten mit status "final" werden zu Fakten. Alle
//      anderen landen in `nicht_final`, damit REF-03 sie melden kann.
//   2. Assertions werden nie verändert. `fakten` ist eine Ableitung; die
//      Beweiskette bleibt in `assertions` rekonstruierbar.

const DOKUMENT_FINAL = 'final';

/** Setzt einen Wert unter einem Punktpfad. Numerische Segmente erzeugen Arrays. */
function setzePfad(ziel, pfad, wert) {
  const teile = pfad.split('.');
  let aktuell = ziel;
  for (let i = 0; i < teile.length - 1; i += 1) {
    const teil = teile[i];
    const naechsterIstIndex = /^[0-9]+$/.test(teile[i + 1]);
    if (aktuell[teil] === undefined) aktuell[teil] = naechsterIstIndex ? [] : {};
    aktuell = aktuell[teil];
  }
  aktuell[teile[teile.length - 1]] = wert;
  return ziel;
}

/** Liest einen Wert unter einem Punktpfad; undefined, wenn der Pfad nicht existiert. */
function liesPfad(quelle, pfad) {
  if (!quelle || !pfad) return undefined;
  return pfad.split('.').reduce((akt, teil) => (akt === undefined || akt === null ? undefined : akt[teil]), quelle);
}

function baueAkte(eingang) {
  const dokumente = new Map((eingang.dokumente || []).map((d) => [d.id, d]));
  const fakten = {};
  const herkunft = {};
  const nichtFinal = [];
  const unbekannteDokumente = [];

  for (const assertion of eingang.assertions || []) {
    const dokument = dokumente.get(assertion.dokument);
    if (!dokument) {
      unbekannteDokumente.push(assertion);
      continue;
    }
    if (dokument.status !== DOKUMENT_FINAL) {
      nichtFinal.push({ ...assertion, dokument_status: dokument.status, dokument_typ: dokument.typ });
      continue;
    }
    setzePfad(fakten, assertion.pfad, assertion.wert);
    herkunft[assertion.pfad] = {
      dokument: dokument.id,
      dokument_typ: dokument.typ,
      konfidenz: assertion.konfidenz ?? 1,
      seite: assertion.seite ?? null,
      methode: assertion.methode ?? null,
    };
  }

  // Sachverhalt und Anmeldung sind keine Belegaussagen, sondern Stammdaten der
  // Akte. Sie liegen direkt am Eingang und werden als Fakten übernommen.
  if (eingang.sachverhalt) fakten.sachverhalt = eingang.sachverhalt;
  if (eingang.anmeldung) fakten.anmeldung = eingang.anmeldung;

  return {
    ...eingang,
    fakten,
    herkunft,
    nicht_final: nichtFinal,
    unbekannte_dokumente: unbekannteDokumente,
  };
}

/** Aktenwert unter einem Pfad. */
function fakt(akte, pfad) {
  return liesPfad(akte.fakten, pfad);
}

/** Konfidenz, mit der ein Fakt extrahiert wurde; 1, wenn er kein Extraktionsergebnis ist. */
function konfidenz(akte, pfad) {
  return akte.herkunft?.[pfad]?.konfidenz ?? 1;
}

/** Alle Dokumente eines Typs, optional nur finale. */
function dokumenteVomTyp(akte, typ, nurFinal = false) {
  return (akte.dokumente || []).filter((d) => d.typ === typ && (!nurFinal || d.status === DOKUMENT_FINAL));
}

// ---- src/regeln/befund.mjs ----
// Einheitliche Form eines Regelergebnisses. Jede Regel in src/regeln/ gibt
// genau das zurück; das Regelwerk ergänzt Regelversion, Härte und Risiko aus
// dem Katalog.
//
// status:
//   ok                      Zusage hält
//   verletzt                Zusage gebrochen — bei harten Regeln keine Freigabe
//   `nicht_pruefbar`        ein Eingabewert fehlt; das ist ein Nachforderungsfall
//   re_extraction_required  Prüfziffern- oder Summenfehler bei niedriger
//                           Konfidenz: zuerst Lesefehler, nicht Fachfehler


const STATUS = Object.freeze({
  OK: 'ok',
  VERLETZT: 'verletzt',
  NICHT_PRUEFBAR: 'nicht_pruefbar',
  RE_EXTRACTION: 're_extraction_required',
});

function ok(eingaben, begruendung) {
  return { status: STATUS.OK, eingaben, begruendung };
}

function verletzt(eingaben, begruendung, extra = {}) {
  return { status: STATUS.VERLETZT, eingaben, begruendung, ...extra };
}

function nichtPruefbar(eingaben, fehlendePfade, begruendung) {
  return { status: STATUS.NICHT_PRUEFBAR, eingaben, fehlende_pfade: fehlendePfade, begruendung };
}

function reExtraction(eingaben, pfade, begruendung) {
  return { status: STATUS.RE_EXTRACTION, eingaben, nachzulesende_pfade: pfade, begruendung };
}

/** Liefert die fehlenden Pfade, damit eine Regel mit einem Aufruf entscheiden kann, ob sie prüfbar ist. */
function fehlend(eingaben) {
  return Object.entries(eingaben)
    .filter(([, wert]) => wert === undefined || wert === null)
    .map(([pfad]) => pfad);
}

/** Welche der beteiligten Werte unter der Konfidenzschwelle gelesen wurden. */
function unsicherGelesen(akte, pfade, defaults) {
  return pfade.filter((pfad) => konfidenz(akte, pfad) < defaults.low_confidence_below);
}

/**
 * Ein Verstoß — es sei denn, er beruht auf unsicher gelesenen Werten.
 *
 * CLAUDE.md, harte Grenze 3: Prüfziffern-, Summen- und Vergleichsfehler sind
 * auf einem Scan meistens Lesefehler und selten Dokumentfehler. Liegt die
 * Extraktionskonfidenz eines beteiligten Wertes unter
 * `defaults.low_confidence_below`, ist das Ergebnis
 * `re_extraction_required` statt `verletzt`: nachlesen vor ablehnen.
 *
 * `pfade` sind die Faktenpfade, auf denen der Vergleich beruht — nur sie,
 * nicht alle Eingaben der Regel. Ein unsicher gelesenes Feld, das am Befund
 * nicht beteiligt war, darf die Ablehnung nicht aufheben.
 */
function verletztWennSicher(akte, pfade, defaults, eingaben, begruendung, extra = {}) {
  const unsicher = unsicherGelesen(akte, pfade, defaults);
  if (unsicher.length === 0) return verletzt(eingaben, begruendung, extra);
  return reExtraction(
    eingaben,
    unsicher,
    `${begruendung} — Konfidenz unter ${defaults.low_confidence_below}: zuerst nachlesen`,
  );
}

// ---- src/regeln/VAL-01.mjs ----
// VAL-01 Rechnungssumme schlüssig.
// Summe der Positionsnetto plus Zuschläge minus Rabatte muss den Endbetrag
// ergeben. Toleranz kommt aus rules.yaml (tolerance.amount), nicht von hier.
// Ein Summenfehler bei niedriger Konfidenz ist zuerst ein Lesefehler (OCR-01).




const REGEL_VAL_01 = 'VAL-01';

function pruefeVAL01(akte, regel, defaults) {
  const positionen = fakt(akte, 'rechnung.positionen');
  const eingaben = {
    'rechnung.positionen': positionen,
    'rechnung.zuschlaege': fakt(akte, 'rechnung.zuschlaege') ?? 0,
    'rechnung.rabatte': fakt(akte, 'rechnung.rabatte') ?? 0,
    'rechnung.gesamt': fakt(akte, 'rechnung.gesamt'),
  };
  const offen = fehlend(eingaben);
  if (offen.length > 0) return nichtPruefbar(eingaben, offen, 'Rechnungspositionen oder Endbetrag fehlen');

  const summe = positionen.reduce((s, p) => s + (p.netto ?? 0), 0)
    + eingaben['rechnung.zuschlaege'] - eingaben['rechnung.rabatte'];
  const gesamt = eingaben['rechnung.gesamt'];
  eingaben.berechnet = summe;

  if (gleichBisAuf(summe, gesamt, regel.tolerance.amount)) {
    return ok(eingaben, `Summe ${summe} entspricht Endbetrag ${gesamt}`);
  }

  const schwelle = defaults.low_confidence_below;
  const unsicher = ['rechnung.gesamt', ...positionen.map((_, i) => `rechnung.positionen.${i}.netto`)]
    .filter((pfad) => konfidenz(akte, pfad) < schwelle);
  if (unsicher.length > 0) {
    return reExtraction(eingaben, unsicher, `Summe ${summe} ≠ Endbetrag ${gesamt}, aber Konfidenz unter ${schwelle}: zuerst nachlesen`);
  }
  return verletzt(eingaben, `Summe der Positionen ${summe} ≠ Endbetrag ${gesamt}`);
}

// ---- src/regeln/VAL-03.mjs ----
// VAL-03 Kostenlose Position hat Zollwert.
// "No charge" heißt nicht "kein Zollwert". Eine Position mit Einzelpreis 0
// braucht einen Zollwert größer 0 oder eine dokumentierte Bewertungsmethode
// (Folgemethoden nach Art. 74 UZK, Verweis aus rules.yaml).



const REGEL_VAL_03 = 'VAL-03';

function pruefeVAL03(akte, regel, defaults) {
  const positionen = fakt(akte, 'rechnung.positionen');
  if (!positionen) return nichtPruefbar({}, ['rechnung.positionen'], 'Rechnungspositionen fehlen');

  const unbewertet = positionen
    .map((p, i) => ({ index: i, ...p }))
    .filter((p) => p.einzelpreis === 0)
    .filter((p) => !(p.zollwert > 0) && !p.bewertungsmethode);

  const eingaben = { kostenlose_positionen: positionen.filter((p) => p.einzelpreis === 0).length };
  if (unbewertet.length === 0) return ok(eingaben, 'Jede kostenlose Position ist bewertet');
  // Ein als 0 gelesener Einzelpreis kann ein Lesefehler sein; dann ist die
  // Position gar nicht kostenlos und die Regel nicht einschlägig.
  const beteiligt = unbewertet.flatMap((p) => [
    `rechnung.positionen.${p.index}.einzelpreis`,
    `rechnung.positionen.${p.index}.zollwert`,
  ]);
  return verletztWennSicher(
    akte,
    beteiligt,
    defaults,
    eingaben,
    `Position(en) ${unbewertet.map((p) => p.index + 1).join(', ')} mit Preis 0 ohne Zollwert und ohne Bewertungsmethode`,
    { positionen: unbewertet.map((p) => p.index) },
  );
}

// ---- src/regeln/ORG-02.mjs ----
// ORG-02 Präferenzursprung deckt Ware.
// Der im Nachweis erklärte Ursprung muss dem Ursprung jeder Rechnungsposition
// entsprechen, und die Position muss im Warenkreis des Nachweises liegen
// (gleiche HS-6). Ein Nachweis für "DE" deckt keine Position mit Ursprung "CN".




const REGEL_ORG_02 = 'ORG-02';

function pruefeORG02(akte, regel, defaults, katalog) {
  if (!fakt(akte, 'sachverhalt.praeferenz_beansprucht')) {
    return ok({}, 'Keine Präferenz beansprucht, Regel nicht einschlägig');
  }
  const eingaben = {
    'rechnung.positionen': fakt(akte, 'rechnung.positionen'),
    'praeferenznachweis.ursprung': fakt(akte, 'praeferenznachweis.ursprung'),
    'praeferenznachweis.warenkreis': fakt(akte, 'praeferenznachweis.warenkreis'),
  };
  const offen = fehlend(eingaben);
  if (offen.length > 0) return nichtPruefbar(eingaben, offen, 'Präferenznachweis oder Rechnungspositionen fehlen');

  // Die Stellenzahl des Vergleichs kommt aus CLS-01, damit beide Regeln
  // dieselbe Granularität verwenden.
  const stellen = katalog.regel('CLS-01').parameters.digits;
  const nachweisUrsprung = normalisiereLand(eingaben['praeferenznachweis.ursprung']);
  const warenkreis = new Set(eingaben['praeferenznachweis.warenkreis'].map((w) => kuerzeWarencode(w.hs6, stellen)));

  const widersprueche = [];
  // Ein falsch gelesenes Ursprungsland oder ein falsch gelesener HS-Code
  // sieht aus wie ein Präferenzwiderspruch. Deshalb sammeln wir, worauf der
  // Befund beruht (CLAUDE.md, harte Grenze 3).
  const beteiligt = [];
  eingaben['rechnung.positionen'].forEach((p, i) => {
    const ursprung = normalisiereLand(p.ursprung);
    if (ursprung !== nachweisUrsprung) {
      widersprueche.push(`Position ${i + 1}: Ursprung ${ursprung ?? 'fehlt'} ≠ Nachweis ${nachweisUrsprung}`);
      beteiligt.push(`rechnung.positionen.${i}.ursprung`, 'praeferenznachweis.ursprung');
    }
    if (!warenkreis.has(kuerzeWarencode(p.hs6, stellen))) {
      widersprueche.push(`Position ${i + 1}: HS ${p.hs6} nicht im Warenkreis des Nachweises`);
      beteiligt.push(`rechnung.positionen.${i}.hs6`);
    }
  });

  if (widersprueche.length === 0) return ok(eingaben, `Nachweis deckt alle Positionen mit Ursprung ${nachweisUrsprung}`);
  return verletztWennSicher(akte, beteiligt, defaults, eingaben, widersprueche.join('; '));
}

// ---- src/regeln/ORG-03.mjs ----
// ORG-03 A.TR ist kein Ursprungsnachweis.
// Die A.TR belegt den Freiverkehr in der Zollunion EU–Türkei, nicht den
// Ursprung. Wird Präferenz beansprucht und der einzige "Nachweis" ist eine
// A.TR, oder der Präferenznachweis trägt selbst den Typ atr, ist das der
// häufigste fachliche Denkfehler bei Nicht-Zöllnern (docs/01).



const REGEL_ORG_03 = 'ORG-03';

const TYP_ATR = 'atr';

function pruefeORG03(akte) {
  const atr = dokumenteVomTyp(akte, TYP_ATR);
  const typ = fakt(akte, 'praeferenznachweis.typ');
  const beansprucht = Boolean(fakt(akte, 'sachverhalt.praeferenz_beansprucht'));
  const eingaben = { atr_vorhanden: atr.length > 0, 'praeferenznachweis.typ': typ, praeferenz_beansprucht: beansprucht };

  if (typ === TYP_ATR) {
    return verletzt(eingaben, 'Der Präferenznachweis ist als A.TR erfasst; A.TR ist ein Freiverkehrs-, kein Ursprungsnachweis');
  }
  if (beansprucht && atr.length > 0 && !typ) {
    return verletzt(eingaben, 'Präferenz beansprucht, aber nur eine A.TR liegt vor — sie setzt keinen Präferenzursprung');
  }
  return ok(eingaben, atr.length > 0 ? 'A.TR liegt vor, setzt aber keinen Ursprung' : 'Keine A.TR in der Akte');
}

// ---- src/regeln/ORG-06.mjs ----
// ORG-06 Wertgrenze Ursprungserklärung.
// Über der Schwelle (rules.yaml parameters.threshold, bezogen auf den Wert der
// Ursprungserzeugnisse, nicht auf den Rechnungsgesamtwert) ist eine
// Ursprungserklärung nur mit REX-Registrierung oder als Ermächtigter Ausführer
// wirksam. Die REX-Nummer wird hier nur strukturell geprüft; die Vergabe
// braucht das REX-Portal (Stufe 2).




const REGEL_ORG_06 = 'ORG-06';

const TYP_URSPRUNGSERKLAERUNG = 'origin_declaration';

function pruefeORG06(akte, regel, defaults) {
  const typ = fakt(akte, 'praeferenznachweis.typ');
  if (typ !== TYP_URSPRUNGSERKLAERUNG) {
    return ok({ 'praeferenznachweis.typ': typ }, 'Kein Ursprungserklärungs-Nachweis, Wertgrenze nicht einschlägig');
  }
  const schwelle = regel.parameters.threshold;
  const eingaben = {
    'praeferenznachweis.typ': typ,
    'praeferenznachweis.ursprungswert': fakt(akte, 'praeferenznachweis.ursprungswert'),
    'praeferenznachweis.rex_nummer': fakt(akte, 'praeferenznachweis.rex_nummer') ?? null,
    'praeferenznachweis.ermaechtigter_ausfuehrer': fakt(akte, 'praeferenznachweis.ermaechtigter_ausfuehrer') ?? null,
    schwelle: `${schwelle.value} ${schwelle.currency}`,
  };
  if (eingaben['praeferenznachweis.ursprungswert'] === undefined) {
    return nichtPruefbar(eingaben, ['praeferenznachweis.ursprungswert'], 'Wert der Ursprungserzeugnisse fehlt');
  }
  // Die Währung der Schwelle ist EUR. Eine Umrechnung anderer Währungen ist
  // nicht gebaut (docs/OFFENE-PUNKTE.md); ein anderer Wert ist nicht prüfbar.
  const waehrung = fakt(akte, 'rechnung.waehrung');
  if (waehrung && waehrung !== schwelle.currency) {
    return nichtPruefbar(eingaben, ['rechnung.waehrung'], `Schwelle in ${schwelle.currency}, Rechnung in ${waehrung}: Umrechnung nicht implementiert`);
  }
  if (eingaben['praeferenznachweis.ursprungswert'] <= schwelle.value) {
    return ok(eingaben, 'Ursprungswert unter der Schwelle, jeder Ausführer darf erklären');
  }
  const rex = eingaben['praeferenznachweis.rex_nummer'];
  if (rex && formatGueltig('rex', rex)) return ok(eingaben, `Über der Schwelle, REX ${rex} strukturell gültig`);
  if (eingaben['praeferenznachweis.ermaechtigter_ausfuehrer']) return ok(eingaben, 'Über der Schwelle, Ermächtigter Ausführer erfasst');
  // Ein unscharf gelesener Ursprungswert kann die Schwelle scheinbar reißen,
  // eine unscharf gelesene REX-Nummer scheinbar das Format brechen. Beides
  // ist zuerst ein Lesefehler (CLAUDE.md, harte Grenze 3).
  return verletztWennSicher(
    akte,
    ['praeferenznachweis.ursprungswert', 'praeferenznachweis.rex_nummer'],
    defaults,
    eingaben,
    rex
      ? `REX-Nummer ${rex} entspricht nicht dem Format`
      : `Ursprungswert über ${schwelle.value} ${schwelle.currency} ohne REX-Nummer oder Ermächtigten Ausführer`,
  );
}

// ---- src/regeln/CLS-01.mjs ----
// CLS-01 HS-6 konsistent über alle Belege.
// Rechnung, Packliste und Präferenznachweis müssen je Position dieselben
// ersten Stellen tragen (parameters.digits). Ursprungsregeln sind HS-basiert;
// eine Abweichung ist ein Tarifierungsstreit, bevor er entsteht.
//
// Ein falsch gelesener HS-Code sieht wie eine Abweichung aus. Deshalb der
// Konfidenzpfad (CLAUDE.md, harte Grenze 3).




const REGEL_CLS_01 = 'CLS-01';

function pruefeCLS01(akte, regel, defaults) {
  const stellen = regel.parameters.digits;
  const rechnung = fakt(akte, 'rechnung.positionen');
  if (!rechnung) return nichtPruefbar({}, ['rechnung.positionen'], 'Rechnungspositionen fehlen');

  const packliste = fakt(akte, 'packliste.positionen') ?? [];
  const warenkreis = fakt(akte, 'praeferenznachweis.warenkreis') ?? [];
  const eingaben = { stellen, positionen: rechnung.length };
  const abweichungen = [];
  const beteiligt = [];

  rechnung.forEach((p, i) => {
    const referenz = kuerzeWarencode(p.hs6, stellen);
    if (!referenz) {
      abweichungen.push(`Position ${i + 1}: HS-Code auf der Rechnung fehlt`);
      beteiligt.push(`rechnung.positionen.${i}.hs6`);
      return;
    }
    const packIndex = packliste.findIndex((q) => q.nr === p.nr);
    const pack = packliste[packIndex];
    if (pack?.hs6 && kuerzeWarencode(pack.hs6, stellen) !== referenz) {
      abweichungen.push(`Position ${i + 1}: Rechnung ${referenz} ≠ Packliste ${kuerzeWarencode(pack.hs6, stellen)}`);
      beteiligt.push(`rechnung.positionen.${i}.hs6`, `packliste.positionen.${packIndex}.hs6`);
    }
    const nachweisIndex = warenkreis.findIndex((w) => w.pos === p.nr);
    const nachweis = warenkreis[nachweisIndex];
    if (nachweis?.hs6 && kuerzeWarencode(nachweis.hs6, stellen) !== referenz) {
      abweichungen.push(`Position ${i + 1}: Rechnung ${referenz} ≠ Präferenznachweis ${kuerzeWarencode(nachweis.hs6, stellen)}`);
      beteiligt.push(`rechnung.positionen.${i}.hs6`, `praeferenznachweis.warenkreis.${nachweisIndex}.hs6`);
    }
  });

  if (abweichungen.length === 0) return ok(eingaben, `HS-${stellen} über alle Belege identisch`);
  return verletztWennSicher(akte, beteiligt, defaults, eingaben, abweichungen.join('; '));
}

// ---- src/regeln/CLS-02.mjs ----
// CLS-02 Stellenzahl Warennummer.
// Ausfuhr: 8 Stellen (KN). Einfuhr Deutschland: 11 Stellen (EZT). Die Zahlen
// stehen in rules.yaml unter parameters.length_by_direction.



const REGEL_CLS_02 = 'CLS-02';

function pruefeCLS02(akte, regel) {
  const richtung = fakt(akte, 'anmeldung.richtung');
  const warennummern = fakt(akte, 'anmeldung.warennummern');
  const eingaben = { 'anmeldung.richtung': richtung, 'anmeldung.warennummern': warennummern };
  if (!richtung || !warennummern) {
    return nichtPruefbar(eingaben, [!richtung && 'anmeldung.richtung', !warennummern && 'anmeldung.warennummern'].filter(Boolean), 'Anmeldedaten fehlen');
  }
  const erwartet = regel.parameters.length_by_direction[richtung];
  if (erwartet === undefined) return nichtPruefbar(eingaben, [], `Keine Stellenzahl für Richtung ${richtung} hinterlegt`);

  const falsch = warennummern.filter((n) => String(n).replace(/\s/g, '').length !== erwartet || !/^[0-9]+$/.test(String(n).replace(/\s/g, '')));
  if (falsch.length === 0) return ok(eingaben, `Alle Warennummern ${erwartet}-stellig`);
  return verletzt(eingaben, `Warennummer(n) ${falsch.join(', ')} nicht ${erwartet}-stellig für ${richtung}`);
}

// ---- src/regeln/QTY-01.mjs ----
// QTY-01 Menge Rechnung gegen Packliste.
// Je Position: Rechnungsmenge = Packlistenmenge − dokumentierte Backorders.
// Stückware kennt keine Toleranz (docs/03, Toleranzprofil).
//
// Eine abweichende Menge kann ein Lesefehler sein — auf einem Scan sogar
// häufiger als ein echter Mengenfehler. Deshalb der Konfidenzpfad
// (CLAUDE.md, harte Grenze 3).



const REGEL_QTY_01 = 'QTY-01';

function pruefeQTY01(akte, regel, defaults) {
  const rechnung = fakt(akte, 'rechnung.positionen');
  const packliste = fakt(akte, 'packliste.positionen');
  const eingaben = { 'rechnung.positionen': rechnung, 'packliste.positionen': packliste };
  const offen = [!rechnung && 'rechnung.positionen', !packliste && 'packliste.positionen'].filter(Boolean);
  if (offen.length > 0) return nichtPruefbar(eingaben, offen, 'Rechnungs- oder Packlistenpositionen fehlen');

  const backorders = fakt(akte, 'packliste.backorders') ?? [];
  const abweichungen = [];
  const beteiligt = [];
  rechnung.forEach((p, i) => {
    const packIndex = packliste.findIndex((q) => q.nr === p.nr);
    const pack = packliste[packIndex];
    if (!pack) {
      abweichungen.push(`Position ${i + 1} fehlt in der Packliste`);
      return;
    }
    const backorder = backorders.find((b) => b.nr === p.nr)?.menge ?? 0;
    const erwartet = pack.menge - backorder;
    if (p.menge !== erwartet) {
      abweichungen.push(`Position ${i + 1}: Rechnung ${p.menge} ≠ Packliste ${pack.menge}${backorder ? ` − Backorder ${backorder}` : ''}`);
      beteiligt.push(`rechnung.positionen.${i}.menge`, `packliste.positionen.${packIndex}.menge`);
    }
  });

  if (abweichungen.length === 0) return ok(eingaben, 'Mengen je Position identisch');
  return verletztWennSicher(akte, beteiligt, defaults, eingaben, abweichungen.join('; '));
}

// ---- src/regeln/QTY-02.mjs ----
// QTY-02 Bruttogewicht Packliste gegen B/L.
// Weiche Regel: Warnung, wenn die Abweichung die Toleranz überschreitet
// (max aus relativ und absolut, rules.yaml). Ab escalate_to_hard_at wird sie
// hart. Es gibt keine gesetzliche EU-Zolltoleranz; die Werte sind
// Praxisannahmen (source_type practice).
//
// Ein unscharf gelesenes Gewicht ist zuerst ein Lesefehler, nicht eine
// Gewichtsabweichung (CLAUDE.md, harte Grenze 3).




const REGEL_QTY_02 = 'QTY-02';

function pruefeQTY02(akte, regel, defaults) {
  const eingaben = {
    'packliste.brutto_gesamt_kg': fakt(akte, 'packliste.brutto_gesamt_kg'),
    'bill_of_lading.brutto_kg': fakt(akte, 'bill_of_lading.brutto_kg'),
  };
  const offen = fehlend(eingaben);
  if (offen.length > 0) return nichtPruefbar(eingaben, offen, 'Bruttogewicht auf Packliste oder B/L fehlt');

  const packliste = eingaben['packliste.brutto_gesamt_kg'];
  const bl = eingaben['bill_of_lading.brutto_kg'];
  const differenz = Math.abs(packliste - bl);
  const relativ = packliste > 0 ? differenz / packliste : Infinity;
  const toleranz = Math.max(regel.tolerance.absolute_kg, regel.tolerance.relative * packliste);
  eingaben.differenz_kg = differenz;
  eingaben.differenz_relativ = gerundet(relativ);
  eingaben.toleranz_kg = toleranz;

  if (differenz <= toleranz) return ok(eingaben, `Abweichung ${differenz} kg innerhalb ${toleranz} kg`);

  const eskaliert = relativ >= regel.escalate_to_hard_at.relative;
  return verletztWennSicher(
    akte,
    ['packliste.brutto_gesamt_kg', 'bill_of_lading.brutto_kg'],
    defaults,
    eingaben,
    `Abweichung ${differenz} kg (${prozent(relativ)}) über Toleranz ${toleranz} kg${eskaliert ? ', über Eskalationsschwelle: hart' : ''}`,
    { haerte_effektiv: eskaliert ? 'hard' : 'soft' },
  );
}

// ---- src/regeln/QTY-03.mjs ----
// QTY-03 Gewichtslogik: brutto ≥ netto > 0 je Packstück und gesamt.
// Reine Logikregel. Vertauschte Spalten sind die häufigste Ursache (docs/01)
// — und ein unscharf gelesenes Gewicht die zweithäufigste. Deshalb der
// Konfidenzpfad (CLAUDE.md, harte Grenze 3).



const REGEL_QTY_03 = 'QTY-03';

function pruefeQTY03(akte, regel, defaults) {
  const packstuecke = fakt(akte, 'packliste.packstuecke');
  if (!packstuecke) return nichtPruefbar({}, ['packliste.packstuecke'], 'Packstücke fehlen');

  const fehler = [];
  const beteiligt = [];
  packstuecke.forEach((p, i) => {
    if (!(p.netto_kg > 0)) {
      fehler.push(`${p.id}: netto ${p.netto_kg} nicht > 0`);
      beteiligt.push(`packliste.packstuecke.${i}.netto_kg`);
    } else if (!(p.brutto_kg >= p.netto_kg)) {
      fehler.push(`${p.id}: brutto ${p.brutto_kg} < netto ${p.netto_kg}`);
      beteiligt.push(`packliste.packstuecke.${i}.brutto_kg`, `packliste.packstuecke.${i}.netto_kg`);
    }
  });
  const bruttoSumme = packstuecke.reduce((s, p) => s + (p.brutto_kg ?? 0), 0);
  const bruttoGesamt = fakt(akte, 'packliste.brutto_gesamt_kg');
  if (bruttoGesamt !== undefined && bruttoSumme > bruttoGesamt) {
    fehler.push(`Summe der Packstücke ${bruttoSumme} kg > Bruttogesamt ${bruttoGesamt} kg`);
    beteiligt.push('packliste.brutto_gesamt_kg', ...packstuecke.map((_, i) => `packliste.packstuecke.${i}.brutto_kg`));
  }
  const eingaben = { packstuecke: packstuecke.length, brutto_summe_kg: bruttoSumme, 'packliste.brutto_gesamt_kg': bruttoGesamt };
  if (fehler.length === 0) return ok(eingaben, 'brutto ≥ netto > 0 für alle Packstücke');
  return verletztWennSicher(akte, beteiligt, defaults, eingaben, fehler.join('; '));
}

// ---- src/regeln/TRN-01.mjs ----
// TRN-01 Containernummer konsistent über B/L und Packliste.
// Vergleich nach Normalisierung (Leerzeichen, Bindestriche, Groß-/Kleinschreibung).
// Eine Abweichung bezeichnet möglicherweise eine andere physische Sendung —
// oder einen Lesefehler: Stammt einer der Werte mit niedriger Konfidenz aus
// der Extraktion, ist Nachlesen der erste Schritt (OCR-01), nicht die Ablehnung.




const REGEL_TRN_01 = 'TRN-01';

function pruefeTRN01(akte, regel, defaults) {
  const eingaben = {
    'bill_of_lading.container_id': fakt(akte, 'bill_of_lading.container_id'),
    'packliste.container_id': fakt(akte, 'packliste.container_id'),
  };
  const offen = fehlend(eingaben);
  if (offen.length > 0) return nichtPruefbar(eingaben, offen, 'Containernummer auf B/L oder Packliste fehlt');

  const bl = normalisiereContainerId(eingaben['bill_of_lading.container_id']);
  const pack = normalisiereContainerId(eingaben['packliste.container_id']);
  if (bl === pack) return ok(eingaben, `Container ${bl} auf beiden Belegen`);
  const unsicher = Object.keys(eingaben).filter((pfad) => konfidenz(akte, pfad) < defaults.low_confidence_below);
  if (unsicher.length > 0) {
    return reExtraction(eingaben, unsicher, `B/L nennt ${bl}, Packliste ${pack}, aber Konfidenz unter ${defaults.low_confidence_below}: zuerst nachlesen`);
  }
  return verletzt(eingaben, `B/L nennt ${bl}, Packliste ${pack}`);
}

// ---- src/regeln/TRN-02.mjs ----
// TRN-02 Container-Prüfziffer ISO 6346.
// Prüfziffernfehler sind zuerst Lesefehler (CLAUDE.md, harte Grenze 3). Liegt
// die Extraktionskonfidenz des Wertes unter defaults.low_confidence_below, wird
// re_extraction_required gesetzt statt fachlich abgelehnt. Bei hoher Konfidenz
// ist es ein echter Dokumentfehler.




const REGEL_TRN_02 = 'TRN-02';

const PFADE = ['bill_of_lading.container_id', 'packliste.container_id'];

function pruefeTRN02(akte, regel, defaults) {
  const eingaben = {};
  const fehlerhaft = [];
  const unsicher = [];
  let geprueft = 0;

  for (const pfad of PFADE) {
    const wert = fakt(akte, pfad);
    if (wert === undefined || wert === null) continue;
    geprueft += 1;
    const ergebnis = pruefeContainerId(wert);
    eingaben[pfad] = { wert, ...ergebnis, konfidenz: konfidenz(akte, pfad) };
    if (ergebnis.format && ergebnis.pruefziffer) continue;
    if (konfidenz(akte, pfad) < defaults.low_confidence_below) unsicher.push(pfad);
    else fehlerhaft.push(`${pfad}: ${ergebnis.id} (${ergebnis.format ? `Prüfziffer erwartet ${ergebnis.erwartet}` : 'Format ungültig'})`);
  }

  if (geprueft === 0) return nichtPruefbar(eingaben, PFADE, 'Keine Containernummer in der Akte');
  if (unsicher.length > 0) {
    return reExtraction(eingaben, unsicher, `Prüfziffer falsch bei Konfidenz unter ${defaults.low_confidence_below}: Nachextraktion vor fachlicher Ablehnung`);
  }
  if (fehlerhaft.length > 0) return verletzt(eingaben, fehlerhaft.join('; '));
  return ok(eingaben, 'Prüfziffer ISO 6346 gültig');
}

// ---- src/regeln/REF-03.mjs ----
// REF-03 Nur finale Dokumentversionen speisen kanonische Fakten.
// Der Aktenaufbau (src/akte/aufbau.mjs) lässt Assertions aus Drafts nie zu
// Fakten werden. Diese Regel macht das sichtbar: Ein Draft, der Werte trägt,
// für die kein finales Dokument desselben Typs existiert, ist ein Befund —
// die Akte stützt sich sonst stillschweigend auf nichts.



const REGEL_REF_03 = 'REF-03';

function pruefeREF03(akte) {
  const nichtFinal = akte.nicht_final ?? [];
  const typenOhneFinal = new Set();
  for (const assertion of nichtFinal) {
    const finale = dokumenteVomTyp(akte, assertion.dokument_typ, true);
    if (finale.length === 0) typenOhneFinal.add(`${assertion.dokument_typ} (${assertion.dokument}, Status ${assertion.dokument_status})`);
  }
  const eingaben = { assertions_nicht_final: nichtFinal.length, typen_ohne_finale_fassung: [...typenOhneFinal] };
  if (typenOhneFinal.size === 0) {
    return ok(eingaben, nichtFinal.length > 0
      ? `${nichtFinal.length} Assertions aus Drafts ignoriert, finale Fassungen liegen vor`
      : 'Alle Fakten stammen aus finalen Dokumenten');
  }
  return verletzt(eingaben, `Nur Entwurf vorhanden für: ${[...typenOhneFinal].join(', ')} — Draft darf keine Anmeldegrundlage sein`);
}

// ---- src/regeln/CUS-05.mjs ----
// CUS-05 Das Ausfuhrbegleitdokument beschreibt dieselbe Sendung wie Rechnung
// und Packliste.
//
// Das ABD ist die lesbare Fassung der überlassenen Ausfuhranmeldung; was
// dort steht, ist angemeldet. Weicht die Warennummer von der Rechnung ab oder
// der Container von der Packliste, ist ein anderer Zollvorgang angemeldet als
// verladen wird. Verglichen werden die ersten `parameters.digits` Stellen der
// Warennummer (die Rechnung trägt HS-6, das ABD die achtstellige KN) und die
// normalisierte Containernummer.
//
// Beide Werte kommen aus der Extraktion; deshalb der Konfidenzpfad
// (CLAUDE.md, harte Grenze 3): Eine unsicher gelesene Warennummer ist zuerst
// ein Lesefehler. Die MRN selbst wird hier nicht geprüft; ihre Struktur
// sichert die Normalisierung, ihr Vorhandensein die Pflichtmatrix (PFL-07).





const REGEL_CUS_05 = 'CUS-05';

function pruefeCUS05(akte, regel, defaults) {
  const stellen = regel.parameters.digits;
  const abdPositionen = fakt(akte, 'abd.positionen');
  const abdContainer = fakt(akte, 'abd.container_id');
  if (!abdPositionen && !abdContainer) {
    return nichtPruefbar({}, ['abd.positionen', 'abd.container_id'], 'Kein Ausfuhrbegleitdokument in der Akte');
  }
  const rechnung = fakt(akte, 'rechnung.positionen');
  if (!rechnung) return nichtPruefbar({}, ['rechnung.positionen'], 'Rechnungspositionen fehlen');

  const packContainer = fakt(akte, 'packliste.container_id');
  const eingaben = { stellen, positionen_abd: (abdPositionen ?? []).length, positionen_rechnung: rechnung.length };
  const abweichungen = [];
  const beteiligt = [];

  (abdPositionen ?? []).forEach((p, i) => {
    const angemeldet = kuerzeWarencode(p.warennummer, stellen);
    const rechnungIndex = rechnung.findIndex((q) => q.nr === p.nr);
    const gegenstueck = rechnung[rechnungIndex];
    if (!gegenstueck) {
      abweichungen.push(`Position ${p.nr} nur im ABD`);
      beteiligt.push(`abd.positionen.${i}.nr`);
      return;
    }
    const berechnet = kuerzeWarencode(gegenstueck.hs6, stellen);
    if (!angemeldet) {
      abweichungen.push(`Position ${p.nr}: Warennummer auf dem ABD fehlt oder ist unlesbar`);
      beteiligt.push(`abd.positionen.${i}.warennummer`);
      return;
    }
    if (berechnet && angemeldet !== berechnet) {
      abweichungen.push(`Position ${p.nr}: Rechnung ${berechnet}, ABD ${angemeldet}`);
      beteiligt.push(`abd.positionen.${i}.warennummer`, `rechnung.positionen.${rechnungIndex}.hs6`);
    }
  });
  rechnung.forEach((q, i) => {
    if (!(abdPositionen ?? []).some((p) => p.nr === q.nr)) {
      abweichungen.push(`Position ${q.nr} nur auf der Rechnung`);
      beteiligt.push(`rechnung.positionen.${i}.nr`);
    }
  });

  let containerText = 'Container nicht vergleichbar, Packliste oder ABD nennt keinen';
  if (abdContainer && packContainer) {
    const abd = normalisiereContainerId(abdContainer);
    const pack = normalisiereContainerId(packContainer);
    if (abd === pack) {
      containerText = `Container ${abd} auf ABD und Packliste`;
    } else {
      abweichungen.push(`Container: ABD ${abd}, Packliste ${pack}`);
      beteiligt.push('abd.container_id', 'packliste.container_id');
    }
  }

  if (abweichungen.length === 0) {
    return ok(eingaben, `${rechnung.length} Positionen auf HS-${stellen} angemeldet wie berechnet; ${containerText}`);
  }
  return verletztWennSicher(akte, beteiligt, defaults, eingaben, abweichungen.join('; '));
}

// ---- src/regeln/index.mjs ----
// Register der implementierten Regeln. Der Katalog (rules.yaml) bestimmt, was
// gilt; dieses Register sagt, was prüfbar ist. scripts/regel-check.mjs stellt
// sicher, dass beide Listen deckungsgleich sind.















const REGELN = Object.freeze({
  'VAL-01': pruefeVAL01,
  'VAL-03': pruefeVAL03,
  'ORG-02': pruefeORG02,
  'ORG-03': pruefeORG03,
  'ORG-06': pruefeORG06,
  'CLS-01': pruefeCLS01,
  'CLS-02': pruefeCLS02,
  'QTY-01': pruefeQTY01,
  'QTY-02': pruefeQTY02,
  'QTY-03': pruefeQTY03,
  'TRN-01': pruefeTRN01,
  'TRN-02': pruefeTRN02,
  'REF-03': pruefeREF03,
  'CUS-05': pruefeCUS05,
});

// ---- src/pflichtmatrix.mjs ----
// Pflichtmatrix: welche Daten müssen nachgewiesen sein, und durch welche Belege.
// Instanziiert aus pflichtmatrix.yaml für den Sachverhalt der Akte.
//
// Ein Eintrag ist erfüllt, wenn der Fakt existiert UND aus einem finalen
// Dokument eines zugelassenen Typs stammt. Das ist Prinzip 1 (Nachweis statt
// Dokument): EUR.1 und Ursprungserklärung erfüllen dieselbe Anforderung.


/** Wertet die einfache Bedingung "pfad == literal" aus; ohne Bedingung gilt der Eintrag. */
function bedingungErfuellt(akte, bedingung) {
  if (!bedingung) return true;
  const treffer = /^([\w.]+)\s*==\s*(\S+)$/.exec(bedingung);
  if (!treffer) throw new Error(`Bedingung nicht lesbar: ${bedingung}`);
  const [, pfad, literal] = treffer;
  const wert = fakt(akte, pfad);
  const erwartet = literal === 'true' ? true : literal === 'false' ? false : literal;
  return wert === erwartet;
}

function scopePasst(scope, sachverhalt) {
  if (!scope) return true;
  return (!scope.direction || scope.direction === sachverhalt?.richtung)
    && (!scope.mode || scope.mode === sachverhalt?.verkehrstraeger)
    && (scope.preference_claimed === undefined || scope.preference_claimed === Boolean(sachverhalt?.praeferenz_beansprucht));
}

function pruefePflichtmatrix(akte, matrix) {
  // Die Fassung der Pflichtmatrix. Ein Override haftet an ihr, damit eine
  // Katalogänderung ihn verbraucht (ADR-007).
  const fassung = `${matrix.version}@${matrix.valid_from}`;
  const sachverhalt = fakt(akte, 'sachverhalt');
  if (!scopePasst(matrix.scope, sachverhalt)) {
    return { anwendbar: false, befunde: [], grund: `Pflichtmatrix ${matrix.version} deckt diesen Sachverhalt nicht` };
  }

  const befunde = [];
  for (const eintrag of matrix.entries) {
    if (!bedingungErfuellt(akte, eintrag.condition)) continue;

    const wert = fakt(akte, eintrag.required_data);
    const herkunft = akte.herkunft?.[eintrag.required_data];
    const basis = {
      id: eintrag.id,
      required_data: eintrag.required_data,
      label: eintrag.label,
      haerte: eintrag.hardness,
      akzeptierte_nachweise: eintrag.required_evidence,
      rechtsgrundlage: eintrag.legal_basis,
      fassung,
    };

    // Stammdaten (sachverhalt.*) haben keine Belegherkunft; ihr Vorhandensein genügt.
    const istStammdatum = eintrag.required_data.startsWith('sachverhalt.') || eintrag.required_data.startsWith('anmeldung.');
    if (wert === undefined || wert === null || wert === '') {
      befunde.push({ ...basis, status: 'fehlt', begruendung: `${eintrag.label}: kein Nachweis in der Akte` });
      continue;
    }
    if (!istStammdatum && herkunft && !eintrag.required_evidence.includes(herkunft.dokument_typ)) {
      befunde.push({
        ...basis,
        status: 'falscher_nachweis',
        begruendung: `${eintrag.label}: stammt aus ${herkunft.dokument_typ}, zugelassen sind ${eintrag.required_evidence.join(', ')}`,
      });
      continue;
    }
    befunde.push({ ...basis, status: 'ok', quelle: herkunft?.dokument ?? 'stammdaten', begruendung: `${eintrag.label} nachgewiesen` });
  }
  return { anwendbar: true, befunde };
}

// liesPfad wird hier nur re-exportiert, damit Aufrufer die Pflichtmatrix ohne
// zweiten Import erweitern können.

// ---- src/override.mjs ----
// Override: Verantwortung neben dem Befund, nie statt seiner (ADR-007).
//
// Ein Mensch kann entscheiden, eine Akte trotz eines Befundes freizugeben.
// Er ändert damit **nicht**, was das Regelwerk gesagt hat — der Befund bleibt
// `verletzt`, und daneben steht, wer die Freigabe verantwortet und warum.
// Auf die Frage nach drei Jahren („welche Regel galt, was sagte sie, wer hat
// sie übersteuert") antwortet dann eine Abfrage statt einer Rekonstruktion.
//
// Ein Override gilt für **eine Kennung in einer Akte zu einer Fassung**.
// Ändert sich der Katalog, ist er verbraucht: Die Person hat eine andere
// Regel verantwortet als die, die jetzt gilt. Das ist unbequem und richtig —
// genau darüber entscheidet eine Zollprüfung.
//
// Die Form entspricht der Tabelle `override` in deploy/postgres/init.sql:
//   `{ regel, benutzer, begruendung, erzeugt_am, fassung }`
// `fassung` ist die Regel- beziehungsweise Pflichtversion, gegen die
// entschieden wurde.

const ANGEWANDT = 'angewandt';
const VERBRAUCHT = 'verbraucht';

/** Die kürzeste Begründung, die noch eine ist — wie der CHECK in der Tabelle. */
const MINDESTLAENGE_BEGRUENDUNG = 11;

/**
 * Prüft die Form eines Overrides. Was hier durchfällt, hätte die Datenbank
 * ohnehin abgelehnt; die Prüfung steht hier, damit ein Aufrufer den Grund
 * erfährt statt eines Constraint-Fehlers.
 */
function formfehler(override) {
  const fehler = [];
  if (!override || typeof override !== 'object') return ['kein Objekt'];
  if (!override.regel) fehler.push('regel fehlt');
  if (!override.benutzer) fehler.push('benutzer fehlt');
  if (!override.fassung) fehler.push('fassung fehlt');
  if (!override.begruendung || String(override.begruendung).trim().length < MINDESTLAENGE_BEGRUENDUNG) {
    fehler.push(`begruendung braucht mindestens ${MINDESTLAENGE_BEGRUENDUNG} Zeichen`);
  }
  return fehler;
}

/**
 * Ordnet die Overrides einer Kennung zu.
 *
 * Liefert den gültigen (gleiche Fassung) und die verbrauchten (andere
 * Fassung). Verbrauchte verschwinden nicht: Sie werden gemeldet, damit
 * sichtbar bleibt, dass jemand einmal entschieden hat und die Entscheidung
 * durch eine Katalogänderung hinfällig wurde.
 */
function ordneZu(overrides, kennung, fassung) {
  const eigene = (overrides ?? []).filter((o) => o && o.regel === kennung);
  const gueltig = eigene.find((o) => o.fassung === fassung && formfehler(o).length === 0) ?? null;
  const verbraucht = eigene.filter((o) => o !== gueltig);
  return { gueltig, verbraucht };
}

/**
 * Hängt die Übersteuerung an einen Befund. Der Status bleibt unberührt —
 * das ist der ganze Punkt dieser ADR.
 */
function hefteAn(befund, kennung, fassung, overrides) {
  const { gueltig, verbraucht } = ordneZu(overrides, kennung, fassung);
  if (!gueltig && verbraucht.length === 0) return befund;
  return {
    ...befund,
    ...(gueltig
      ? {
          uebersteuert_von: gueltig.benutzer,
          uebersteuert_am: gueltig.erzeugt_am ?? null,
          uebersteuerungsgrund: gueltig.begruendung,
          // Woher der Name stammt (ADR-009): `proxy`, wenn nginx ihn geprüft
          // und als Header mitgegeben hat; sonst `angegeben`, also getippt.
          // Ein Audit-Eintrag ohne diese Angabe wäre eine Behauptung.
          uebersteuert_identitaet: gueltig.identitaet ?? 'angegeben',
        }
      : {}),
    ...(verbraucht.length > 0
      ? {
          uebersteuerung_verbraucht: verbraucht.map((o) => ({
            benutzer: o.benutzer,
            fassung: o.fassung,
            erzeugt_am: o.erzeugt_am ?? null,
          })),
        }
      : {}),
  };
}

/** Ob ein Befund für die Freigabe zählt, wenn Übersteuerungen berücksichtigt werden. */
function zaehltTrotzUebersteuerung(befund) {
  return !befund.uebersteuert_von;
}

// ---- src/nachforderung.mjs ----
// Nachforderung: aus Befunden werden konkrete Anforderungen an den
// Dateninhaber. Nie "bitte alle Zollunterlagen" — immer Feld, Position, Grund,
// akzeptierte Nachweise und Folge bei Fristüberschreitung (docs/05).


function zustaendig(pfad, zustaendigkeiten) {
  const praefix = String(pfad).split('.')[0];
  return zustaendigkeiten.owners[praefix] ?? { primaer: 'Sachbearbeitung Export', sekundaer: null, ausloeser: null };
}

function formuliereNachforderungen(ergebnis, zustaendigkeiten) {
  const faelle = [];

  for (const befund of ergebnis.pflichtmatrix.befunde) {
    if (befund.status === 'ok') continue;
    faelle.push({
      grund: befund.id,
      feld: befund.required_data,
      adressat: zustaendig(befund.required_data, zustaendigkeiten),
      anforderung: befund.label,
      widerspruch: befund.begruendung,
      akzeptierte_nachweise: befund.akzeptierte_nachweise,
      folge: befund.haerte === 'hard' ? 'Keine Freigabe der Akte' : 'Freigabe mit Vermerk',
    });
  }

  for (const befund of ergebnis.befunde) {
    if (befund.status === 'ok') continue;
    const pfade = befund.fehlende_pfade ?? befund.nachzulesende_pfade ?? Object.keys(befund.eingaben ?? {}).filter((k) => k.includes('.'));
    const feld = pfade[0] ?? befund.regel;
    faelle.push({
      grund: befund.regel,
      feld,
      adressat: befund.status === 're_extraction_required'
        ? { primaer: 'Extraktion (Nachlesen)', sekundaer: 'Sachbearbeitung Export', ausloeser: 'sofort' }
        : zustaendig(feld, zustaendigkeiten),
      anforderung: befund.name,
      widerspruch: befund.begruendung,
      akzeptierte_nachweise: befund.inputs,
      folge: befund.haerte_effektiv === 'hard' ? `Keine Freigabe: ${befund.konsequenz}` : `Warnung: ${befund.konsequenz}`,
    });
  }

  const eskalation = zustaendigkeiten.escalation?.[0] ?? null;
  return faelle.map((fall) => {
    const mitBetreff = {
      ...fall,
      stufe: eskalation?.stufe ?? 'erinnerung_0',
      betreff: `ACTION REQUIRED – ${fall.anforderung} – Shipment ${ergebnis.akte_id}`,
    };
    return { ...mitBetreff, text: nachforderungstext(mitBetreff, ergebnis) };
  });
}

function nachforderungstext(fall, ergebnis) {
  const referenzen = [
    ['Invoice', liesPfad(ergebnis.referenzen, 'rechnung')],
    ['B/L', liesPfad(ergebnis.referenzen, 'bill_of_lading')],
    ['Container', liesPfad(ergebnis.referenzen, 'container')],
  ].filter(([, wert]) => wert).map(([name, wert]) => `${name} ${wert}`).join(' / ');

  return [
    `Betreff: ${fall.betreff}`,
    '',
    `An: ${fall.adressat.primaer}${fall.adressat.sekundaer ? ` (Kopie: ${fall.adressat.sekundaer})` : ''}`,
    '',
    'Benötigt:',
    `- Dokument/Feld: ${fall.feld}`,
    `- Grund der Anforderung: ${fall.anforderung} (${fall.grund})`,
    `- Gefundener Widerspruch: ${fall.widerspruch}`,
    `- Akzeptierte Nachweise: ${(fall.akzeptierte_nachweise ?? []).join(', ') || 'siehe Regel'}`,
    `- Folge bei Fristüberschreitung: ${fall.folge}`,
    '',
    `Referenzen: ${referenzen || ergebnis.akte_id}`,
  ].join('\n');
}

// ---- src/regelwerk.mjs ----
// Das Regelwerk: der einzige Ort, an dem über Freigabe entschieden wird.
// Deterministisch, auf normalisierten Fakten, ohne Modell (CLAUDE.md, harte
// Grenze 1). Reihenfolge: Akte aufbauen → Pflichtmatrix → harte Regeln →
// weiche Regeln → Freigabe → Nachforderungen.
//
// Der Katalog wird übergeben, nicht geladen: In Tests und im CLI kommt er aus
// rules.yaml (src/katalog.mjs), im n8n-Code-Node aus dem gebündelten JSON
// (scripts/n8n-bundle.mjs). Dieselbe Funktion, dieselben Regeln.






const FREIGABE = Object.freeze({
  FREIGABEREIF: 'freigabereif',
  MIT_WARNUNGEN: 'freigabe_mit_warnungen',
  NACHEXTRAKTION: 'nachextraktion_erforderlich',
  BLOCKIERT: 'blockiert',
});

/** Regel gilt am Stichtag, wenn valid_from ≤ Stichtag < valid_to (valid_to optional). */
function regelGiltAm(regel, stichtag) {
  if (regel.valid_from && stichtag < regel.valid_from) return false;
  if (regel.valid_to && stichtag >= regel.valid_to) return false;
  return true;
}

function katalogZugriff(katalog) {
  const index = new Map(katalog.regeln.rules.map((r) => [r.id, r]));
  return { ...katalog, regel: (id) => index.get(id) };
}

function pruefeAkte(eingang, katalog, register) {
  const akte = baueAkte(eingang);
  const stichtag = eingang.stichtag ?? new Date().toISOString().slice(0, 10);
  const zugriff = katalogZugriff(katalog);
  const defaults = katalog.regeln.defaults;

  // Overrides gehen als Datum in die Auswertung, nie als Eingriff (ADR-007).
  // Das Regelergebnis bleibt, was das Regelwerk sagt; die Verantwortung
  // steht daneben.
  const overrides = eingang.overrides ?? [];

  const pflichtmatrixRoh = pruefePflichtmatrix(akte, katalog.pflichtmatrix);
  const pflichtmatrix = {
    ...pflichtmatrixRoh,
    befunde: pflichtmatrixRoh.befunde.map((b) => hefteAn(b, b.id, b.fassung, overrides)),
  };

  // Harte Regeln zuerst, danach weiche. Innerhalb der Gruppe Katalogreihenfolge.
  const geltend = katalog.regeln.rules.filter((r) => regelGiltAm(r, stichtag));
  const sortiert = [...geltend.filter((r) => r.hardness === 'hard'), ...geltend.filter((r) => r.hardness !== 'hard')];

  const befunde = [];
  const nichtImplementiert = [];
  for (const regel of sortiert) {
    const pruefer = register[regel.id];
    if (!pruefer) {
      nichtImplementiert.push(regel.id);
      continue;
    }
    const ergebnis = pruefer(akte, regel, defaults, zugriff);
    const regelversion = `${katalog.regeln.catalog.version}@${regel.valid_from}`;
    befunde.push(hefteAn({
      regel: regel.id,
      name: regel.name,
      haerte: regel.hardness,
      haerte_effektiv: ergebnis.haerte_effektiv ?? regel.hardness,
      risiko: regel.risk,
      inputs: regel.inputs,
      rechtsgrundlage: regel.legal_basis,
      rechtsquelle_status: regel.legal_source ?? 'secondary',
      konsequenz: regel.consequence,
      regelversion,
      ...ergebnis,
    }, regel.id, regelversion, overrides));
  }

  const freigabe = entscheideFreigabe(befunde, pflichtmatrix);
  const ergebnis = {
    akte_id: eingang.akte_id,
    stichtag,
    katalog_version: katalog.regeln.catalog.version,
    freigabe,
    // Dieselbe Entscheidung, aber mit den übersteuerten Befunden als
    // verantwortet. `freigabe` bleibt unberührt — sonst stünde in der Akte
    // ein Ergebnis, das das Regelwerk nie geliefert hat (ADR-007).
    freigabe_nach_override: entscheideFreigabe(befunde, pflichtmatrix, true),
    uebersteuerungen: {
      angewandt: [...befunde, ...pflichtmatrix.befunde]
        .filter((b) => b.uebersteuert_von)
        .map((b) => ({ kennung: b.regel ?? b.id, benutzer: b.uebersteuert_von, begruendung: b.uebersteuerungsgrund })),
      verbraucht: [...befunde, ...pflichtmatrix.befunde]
        .filter((b) => b.uebersteuerung_verbraucht)
        .flatMap((b) => b.uebersteuerung_verbraucht.map((v) => ({ kennung: b.regel ?? b.id, ...v }))),
    },
    pflichtmatrix,
    befunde,
    regeln_ohne_implementierung: nichtImplementiert,
    // Welche Belege die Akte trägt, mit Status und — wenn sie aus der
    // Extraktion kommen — Seitenzahl, Lesemethode und Hinweis. Ohne das
    // könnte ein Aufrufer nur sehen, was fehlt, nie was erkannt wurde; und
    // ein `unclassified` wäre eine Kennung ohne Grund (CLAUDE.md, harte
    // Grenze 2: nichts stillschweigend verwerfen).
    dokumente: akte.dokumente ?? [],
    extraktion: eingang.extraktion ?? null,
    unbekannte_dokumente: akte.unbekannte_dokumente,
    nicht_klassifiziert: (akte.dokumente ?? []).filter((d) => d.typ === 'unclassified').map((d) => d.id),
    // Die Cut-offs der Akte, unverändert durchgereicht: Der Nachforderungs-
    // Workflow liest sie aus der letzten Prüfung, um Stufen fällig zu stellen
    // (ADR-009). Keine Entscheidung, nur Stammdaten neben dem Ergebnis.
    fristen: eingang.fristen ?? null,
    referenzen: {
      rechnung: fakt(akte, 'rechnung.nummer') ?? null,
      bill_of_lading: fakt(akte, 'bill_of_lading.nummer') ?? null,
      container: fakt(akte, 'bill_of_lading.container_id') ?? fakt(akte, 'packliste.container_id') ?? null,
    },
  };
  ergebnis.nachforderungen = formuliereNachforderungen(ergebnis, katalog.zustaendigkeiten);
  return ergebnis;
}

/**
 * Die Freigabe aus den Befunden.
 *
 * `mitOverride` lässt übersteuerte Befunde außer Betracht — sie bleiben
 * `verletzt`, aber ein Mensch hat sie verantwortet. Ohne das Kennzeichen
 * liefert die Funktion, was das Regelwerk allein sagt.
 */
function entscheideFreigabe(befunde, pflichtmatrix, mitOverride = false) {
  const zaehlt = (b) => !mitOverride || zaehltTrotzUebersteuerung(b);
  const offen = befunde.filter(zaehlt);
  const pflicht = pflichtmatrix.befunde.filter(zaehlt);

  const pflichtHart = pflicht.some((b) => b.status !== 'ok' && b.haerte === 'hard');
  const hartVerletzt = offen.some((b) => b.haerte_effektiv === 'hard' && (b.status === STATUS.VERLETZT || b.status === STATUS.NICHT_PRUEFBAR));
  if (pflichtHart || hartVerletzt) return FREIGABE.BLOCKIERT;
  if (offen.some((b) => b.status === STATUS.RE_EXTRACTION)) return FREIGABE.NACHEXTRAKTION;
  const warnung = offen.some((b) => b.status !== STATUS.OK) || pflicht.some((b) => b.status !== 'ok');
  return warnung ? FREIGABE.MIT_WARNUNGEN : FREIGABE.FREIGABEREIF;
}


// ---- n8n-Einstieg ----
// Der Webhook liefert { headers, params, query, body }; ein Vorgänger-Node kann
// die Akte auch direkt als json liefern.
const roh = $input.first().json;
const eingang = roh.body ?? roh;

// Identität (ADR-009): Hinter dem Proxy kommt der geprüfte Benutzername als
// Header X-Benutzer und ersetzt den getippten Namen jeder Übersteuerung.
// Ohne Proxy bleibt der Name eine Angabe, und der Befund sagt das. Das ist
// Transport: Wer angemeldet ist, weiß nur diese Schicht.
const kopf = roh.headers ?? {};
const benutzerGeprueft = kopf['x-benutzer'] || kopf['X-Benutzer'] || null;
if (Array.isArray(eingang.overrides)) {
  eingang.overrides = eingang.overrides.map((o) => ({ ...o, benutzer: benutzerGeprueft ?? o.benutzer, identitaet: benutzerGeprueft ? 'proxy' : 'angegeben' }));
}
const ergebnis = pruefeAkte(eingang, KATALOG, REGELN);

// Die Ausführungs-ID gehört nicht in die Entscheidung, sondern an sie:
// Mit ihr findet der Betrieb die Ausführung in n8n wieder, mit Eingabe und
// Ausgabe je Node. Sie entsteht im Transport und wird deshalb hier
// angehängt, nicht in src/regelwerk.mjs (ADR-004).
ergebnis.ausfuehrung = typeof $execution === 'undefined' ? null : ($execution.id ?? null);
return [{ json: ergebnis }];

// Transport, keine Entscheidung: Das Formularfeld `akte` (Stammdaten als JSON)
// und die hochgeladenen Dateien werden in das JSON verpackt, das der
// Extraktionsdienst erwartet. Welche Datei welcher Beleg ist, entscheidet der
// Dienst (Klassifikation), nicht dieser Node.
//
// Zweite Form: Kommt der Rumpf bereits als JSON mit `dateien[]` (Base64),
// wird er unverändert durchgereicht. So wiederholt zollpilot-wiederholen
// einen gescheiterten Lauf über denselben Eingang.
const item = $input.first();
const body = item.json.body ?? {};
if (Array.isArray(body.dateien)) {
  return [{ json: { akte: body.akte ?? {}, dateien: body.dateien } }];
}
const roh = body.akte;
const akte = typeof roh === 'string' ? JSON.parse(roh) : (roh ?? {});
const dateien = [];
for (const [schluessel, binaer] of Object.entries(item.binary ?? {})) {
  const puffer = await this.helpers.getBinaryDataBuffer(0, schluessel);
  dateien.push({ name: binaer.fileName ?? `${schluessel}.pdf`, inhalt_base64: puffer.toString('base64') });
}
return [{ json: { akte, dateien } }];

// Transport, keine Entscheidung: Welcher Eingang lief, und was müsste erneut
// hinein, damit der Lauf wiederholt werden kann. Das landet in `wiedervorlage`
// (mit Nutzdaten, docs/DATENSCHUTZ.md), nicht in `workflow_fehler`.
//
// Drei Fälle:
//   Akte-Eingang            der Rumpf des Webhooks, erneut an /webhook/akte
//   Belege, Extraktion ok   die extrahierte Akte, erneut an /webhook/akte
//                           (die PDFs müssen nicht noch einmal gelesen werden)
//   Belege, Extraktion tot  das verpackte JSON, erneut an /webhook/belege
// Scheitert schon das Verpacken, gibt es nichts zu wiederholen.
//
// Zwei Fallen beim Lesen der Vorgänger: `isExecuted` gibt es nur in
// Ausdrücken, nicht im Code-Node; und ein Node, dessen Fehlerausgang genommen
// wurde, hat seine Daten auf Ausgang 1, nicht auf Ausgang 0. Deshalb wird
// jeder Zugriff abgefangen, und ein Node, der nicht lief, ist einfach null.
const ausgabe = (name) => {
  for (const ausgang of [0, 1]) {
    try {
      const item = $(name).first(ausgang);
      if (item && item.json) return item.json;
    } catch (e) { /* nicht gelaufen oder kein Item auf diesem Ausgang */ }
  }
  return null;
};
let eingang = 'akte';
let nutzlast = null;
if (!ausgabe('Belege eingegangen')) {
  nutzlast = ausgabe('Akte eingegangen')?.body ?? null;
} else {
  const extrahiert = ausgabe('Belege extrahieren');
  const verpackt = ausgabe('Belege verpacken');
  if (Array.isArray(extrahiert?.dokumente)) {
    nutzlast = extrahiert;
  } else if (Array.isArray(verpackt?.dateien)) {
    eingang = 'belege';
    nutzlast = verpackt;
  }
}
const akteId = nutzlast?.akte_id ?? nutzlast?.akte?.akte_id ?? null;
return [{
  json: {
    execution_id: String($execution.id),
    eingang,
    akte_id: akteId,
    nutzlast: nutzlast ? JSON.stringify(nutzlast) : null,
    status: nutzlast ? 'offen' : 'nicht_wiederholbar',
  },
}];
